SELECT DISTINCT activity_id, md.chembl_id AS molecule_chembl_id, td.chembl_id AS target_chembl_id, td.pref_name AS target_name, standard_type, standard_value, standard_units FROM activities JOIN molecule_dictionary md ON activities.molregno = md.molregno JOIN assays a ON activities.assay_id = a.assay_id JOIN target_dictionary td ON a.tid = td.tid WHERE td.organism = 'Homo sapiens' AND td.target_type = 'SINGLE PROTEIN' AND activities.standard_units = 'nM' AND activities.standard_type IN ('EC50', 'IC50', 'AC50') AND activities.standard_value < 50 ORDER BY activity_id LIMIT 200
